UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Edilgen yapı kurulurken durumun NÖTR mü yoksa ANİ mi olduğuna bak:", "items": [{"heading": "be passive: Nötr, Resmi, Süregelen", "badge": "be + V3", "body": [{"type": "text", "text": "Durum [[dark]]NÖTR[[/dark]], [[dark]]RESMİ[[/dark]] ve süregelen bir gerçekse (bir kural, bir açıklama, bir rapor) [[ok]]be + past participle[[/ok]] tercih edilir."}, {"type": "example_check", "correct": "The report is reviewed every month", "wrong_note": "burada ani/beklenmedik bir durum yok, nötr bir kural anlatılıyor"}]}, {"heading": "get passive: Ani, Beklenmedik Değişim", "badge": "get + V3", "body": [{"type": "text", "text": "Durum [[dark]]ANİ[[/dark]], [[dark]]BEKLENMEDİK[[/dark]], genellikle OLUMSUZ veya günlük konuşma diline ait bir DEĞİŞİMİ anlatıyorsa (kırılma, kaybolma, şaşırtma gibi) [[ok]]get + past participle[[/ok]] kullanılır."}, {"type": "example_check", "correct": "My phone got stolen last night", "wrong_note": "\"was stolen\" gramer olarak mümkündür ama \"got stolen\" anîliği/sürprizi daha doğal verir"}]}, {"heading": "İpucu Zarflar", "body": [{"type": "text", "text": "[[amber]]\"suddenly\"[[/amber]], [[amber]]\"unexpectedly\"[[/amber]], [[amber]]\"accidentally\"[[/amber]] gibi zarflarla birlikte get passive kullanılması çok daha doğaldır; resmi/akademik metinlerde be passive, günlük diyalog veya anlatıda ani bir olayda get passive aranmalıdır."}]}], "examples": [{"sentence": "According to the company policy, all expenses must be reported within thirty days.", "answer_word": "must be reported", "reasoning": "Burada resmi bir kural/politika anlatıldığı için nötr [[right]]be passive[[/right]] tercih edilir → doğru cevap [[right]]\"must be reported\"[[/right]]tur."}, {"sentence": "The old bridge was built in the 1800s and is still used today.", "answer_word": "was built", "reasoning": "Burada tarihi, nötr bir bilgi aktarılıyor, ani/beklenmedik bir durum yok → doğru cevap sade [[right]]be passive[[/right]] [[right]]\"was built\"[[/right]]tir; [[wrong]]\"got built\"[[/wrong]] yazmak günlük/gayriresmî bir ton katar ve resmi-tarihi bir anlatımla uyuşmaz."}, {"sentence": "Halfway through the ceremony, the microphone suddenly got switched off and the speaker had to continue without it.", "answer_word": "got switched off", "reasoning": "Burada ANİ ve beklenmedik bir arıza anlatıldığı için (\"suddenly\") doğru cevap [[right]]get passive[[/right]] [[right]]\"got switched off\"[[/right]]tur; [[wrong]]\"was switched off\"[[/wrong]] burada daha nötr/kasıtlı bir eylem izlenimi verir ve ânîliğin sürpriz etkisini taşımaz."}, {"sentence": "In most European countries, primary education is funded entirely by the government.", "answer_word": "is funded", "reasoning": "Resmi, genel-geçer bir politika/gerçek anlatıldığı için doğru cevap [[right]]be passive[[/right]] [[right]]\"is funded\"[[/right]]tur; [[wrong]]\"gets funded\"[[/wrong]] burada günlük ve rastlantısal bir ton katar, akademik/resmi anlatımla uyuşmaz."}]}$tagbd$::jsonb WHERE id = 'a19e82af-6b2d-4137-a9b1-784e7cd1ab49';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Karşılaştırma sorularında önce sıfatın hece sayısına, sonra cümlede [[q]]\"than\"[[/q]] mi [[q]]\"the\"[[/q]] mi olduğuna bak:", "items": [{"heading": "-er/-est mi, more/most mu?", "badge": "Hece Kuralı", "sub_rules": [{"condition": "Tek heceli sıfatlara (ve -y ile biten iki hecelilere) [[amber]]\"-er/-est\"[[/amber]] eklenir:", "from": "happy", "to": "happier"}, {"condition": "İki heceden uzun sıfatlara [[amber]]\"more/most\"[[/amber]] eklenir:", "from": "beautiful", "to": "more beautiful"}], "body": [{"type": "text", "text": "İki kuralı karıştırıp [[bad]]\"more taller\"[[/bad]] veya [[bad]]\"beautifuler\"[[/bad]] gibi İKİ karşılaştırma işaretini birden kullanmak (double comparative hatası) klasik bir yanlış şık tuzağıdır."}]}, {"heading": "Düzensiz Sıfatlar", "badge": "Ezbere Bilinmeli", "body": [{"type": "text", "text": "[[b]]good[[/b]] → better → best, [[b]]bad[[/b]] → worse → worst, [[b]]far[[/b]] → farther/further → farthest/furthest, [[b]]little[[/b]] → less → least, [[b]]many/much[[/b]] → more → most."}]}, {"heading": "than mı, the mı?", "body": [{"type": "text", "text": "Cümlede [[amber]]\"than\"[[/amber]] varsa mutlaka KARŞILAŞTIRMA formu (-er/more) gelir; [[amber]]\"the\"[[/amber]] ile başlayan üstünlük cümlelerinde ise SÜPERLATİF (-est/most) formu aranır."}]}, {"heading": "the + comparative..., the + comparative...", "badge": "Paralel Artış/Azalış", "body": [{"type": "text", "text": "Bu kalıp ([[q]]\"The more you practice, the better you get\"[[/q]]) iki şeyin birlikte ARTTIĞINI/AZALDIĞINI anlatan özel bir yapıdır ve sınavlarda sıkça çeldirici olarak kullanılır."}]}], "examples": [{"sentence": "This year's exam was more difficult than last year's, but it was far from being the most difficult exam students have ever taken.", "answer_word": "more difficult", "reasoning": "İlk boşlukta \"than\" olduğu için karşılaştırma formu gerekir → [[right]]\"more difficult\"[[/right]]; ikinci boşlukta \"the\" ile üstünlük anlatıldığı için süperlatif gerekir → [[right]]\"the most difficult\"[[/right]]."}, {"sentence": "The more you practice your pronunciation, the more natural you will sound to native speakers.", "answer_word": "the more natural", "reasoning": "Bu kalıp iki şeyin birlikte değiştiğini anlatan [[q]]\"the + comparative..., the + comparative...\"[[/q]] yapısıdır → doğru cevap [[right]]\"The more ... the more natural\"[[/right]] (ya da benzer bir çift karşılaştırma) olmalıdır; sıfatları çıplak haliyle ([[wrong]]\"More you practice\"[[/wrong]]) kullanmak bu kalıpta yanlıştır, başına mutlaka [[b]]\"the\"[[/b]] gelmelidir."}, {"sentence": "Since switching to a new diet, he has felt better than he did last year, but his doctor says his cholesterol levels are still worse than the recommended range.", "answer_word": "better", "reasoning": "\"than\" kelimesi her iki boşlukta da KARŞILAŞTIRMA formunu tetikler; \"good\" sıfatının düzensiz hali [[right]]\"better\"[[/right]]dir ([[wrong]]\"gooder\"[[/wrong]]/[[wrong]]\"more good\"[[/wrong]] yanlıştır), \"bad\" sıfatının düzensiz hali ise [[right]]\"worse\"[[/right]]tür ([[wrong]]\"more bad\"[[/wrong]]/[[wrong]]\"badder\"[[/wrong]] yanlıştır)."}, {"sentence": "The sooner you submit your application, the higher your chances of receiving the scholarship.", "answer_word": "the higher", "reasoning": "Cümle [[q]]\"the + comparative..., the + comparative...\"[[/q]] kalıbıdır (iki şeyin birlikte değiştiğini anlatır) → doğru cevap [[right]]\"the higher\"[[/right]]dir; [[wrong]]\"higher\"[[/wrong]] tek başına ya da [[wrong]]\"more high\"[[/wrong]] bu kalıpta yanlıştır, ikinci tarafın da mutlaka [[b]]\"the\"[[/b]] ile başlaması gerekir."}]}$tagbd$::jsonb WHERE id = '36f0d9db-0f6c-4b8a-8139-4569ec608f30';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Birleşik isimlerde çoğul ekinin NEREYE eklendiği, bileşiğin türüne göre değişir:", "items": [{"heading": "Birleşik İsimlerde Çoğul Kuralı", "badge": "Üç Durum", "sub_rules": [{"condition": "[[q]]noun + noun[[/q]] bileşiklerinde çoğul eki SADECE SON kelimeye eklenir:", "from": "bus stop", "to": "bus stops"}, {"condition": "[[q]]sayı + isim[[/q]] isimden önce sıfat olarak kullanıldığında ilk kelime HER ZAMAN TEKİL kalır:", "from": "a ten-year-old boy", "to": "a ten-year-old boy (ASLA ten-years-old değil)"}, {"condition": "Tireli bileşik isimlerde ([[q]]mother-in-law[[/q]] gibi) çoğul eki ANA isim olan İLK kısma eklenir:", "from": "mother-in-law", "to": "mothers-in-law"}]}, {"heading": "Sık Yanlış Biçimler", "body": [{"type": "text", "text": "[[bad]]\"buses stop\"[[/bad]], [[bad]]\"a ten-years-old boy\"[[/bad]] ve [[bad]]\"mother-in-laws\"[[/bad]] üçü de bu kuralları ihlal ettiği için yanlıştır."}]}], "examples": [{"sentence": "The new hotel has two swimming pools on its top floor, both with a view of the sea.", "answer_word": "swimming pools", "reasoning": "Burada \"swimming pool\" bir noun+noun bileşiği olduğu için çoğul eki sadece son kelimeye eklenir → doğru cevap [[right]]\"swimming pools\"[[/right]]tur; [[wrong]]\"swimmings pool\"[[/wrong]] kesinlikle yanlıştır."}, {"sentence": "She is the proud mother of a four-year-old girl who already speaks two languages.", "answer_word": "four-year-old", "reasoning": "Burada sayı+isim yapısı (\"four-year-old\") bir sıfat öbeği olarak isimden ÖNCE kullanıldığı için tireli ve TEKİL kalmalıdır → doğru cevap [[right]]\"four-year-old\"[[/right]]dur; [[wrong]]\"four-years-old\"[[/wrong]] yanlıştır."}, {"sentence": "Both of my mothers-in-law are coming to the wedding next month.", "answer_word": "mothers-in-law", "reasoning": "\"mother-in-law\" tireli bir bileşik isim olduğu ve ASIL isim ilk kısımda (\"mother\") olduğu için çoğul eki ilk kelimeye eklenir → doğru cevap [[right]]\"mothers-in-law\"[[/right]]dur; [[wrong]]\"mother-in-laws\"[[/wrong]] bu istisnayı ihlal ettiği için yanlıştır."}, {"sentence": "The company just signed a five-year contract with its biggest supplier.", "answer_word": "five-year", "reasoning": "\"five year\" burada bir SAYI+İSİM yapısı olup \"contract\" isminden ÖNCE sıfat görevi gördüğü için tireli ve TEKİL kalmalıdır → doğru cevap [[right]]\"five-year\"[[/right]]dir; [[wrong]]\"five-years\"[[/wrong]] yanlıştır çünkü bu artık bir isim değil, bir sıfat öbeğidir."}]}$tagbd$::jsonb WHERE id = 'd583d6a3-4018-4b72-89a4-f93bf680c420';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "[[q]]\"by\"[[/q]] ve [[q]]\"until/till\"[[/q]] farklı bir zaman ilişkisi anlatır — boşluktan önceki fiile bak:", "items": [{"heading": "by: Tamamlanma / Deadline", "badge": "Tek Seferlik Eylem", "body": [{"type": "text", "text": "[[q]]\"by\"[[/q]] bir eylemin en geç ne zamana kadar TAMAMLANMIŞ olması gerektiğini belirtir; genellikle bitiş/tamamlanma bildiren fiillerle kullanılır: [[amber]]finish, complete, submit, arrive, hand in[[/amber]]."}, {"type": "example_check", "correct": "Submit the report by Friday", "wrong_note": "en geç Cuma'ya kadar rapor teslim edilmiş olmalı, Cuma'dan sonra değil"}]}, {"heading": "until/till: Süreklilik", "badge": "Devam Eden Durum", "body": [{"type": "text", "text": "[[q]]\"until/till\"[[/q]] bir durumun ya da sürekli bir eylemin ne zamana kadar DEVAM EDECEĞİNİ anlatır; süreklilik bildiren fiillerle kullanılır: [[amber]]stay, wait, work, live, remain, continue[[/amber]]."}, {"type": "example_check", "correct": "Wait until 5 pm", "wrong_note": "saat 5'e kadar beklemeye devam et anlamı taşır"}]}, {"heading": "not...until vs not...by", "is_warning": true, "warning_label": "🔥 EN SIK TUZAK", "body": [{"type": "text", "text": "[[b]]\"not...until\"[[/b]] kalıbı, bir şeyin o ana kadar GERÇEKLEŞMEYECEĞİNİ (ancak ondan sonra olacağını) anlatır:"}], "meaning_pairs": [[{"word": "not...until", "meaning": "o ana kadar gerçekleşmeyecek, ancak sonra olacak"}, {"word": "not...by", "meaning": "en geç o tarihte gerçekleşmiş olmalı", "variant": "wrong"}]], "warning_text": "Bu iki kalıp birbirine çok benzer göründüğü için sınavda sıkça karıştırılır."}], "examples": [{"sentence": "Please make sure all the documents are ready by Monday morning at the latest.", "answer_word": "by", "reasoning": "Burada \"ready\" olma durumu bir DEADLINE'a (en geç Pazartesi) bağlı, tamamlanmış olma hali söz konusu → doğru cevap [[right]]\"by\"[[/right]]dır."}, {"sentence": "The shop will remain closed until the renovation work is fully completed.", "answer_word": "until", "reasoning": "Burada \"remain closed\" sürekli bir durumu anlatıyor ve bu durum bir noktaya KADAR devam edecek → doğru cevap [[right]]\"until\"[[/right]]dur; [[wrong]]\"by\"[[/wrong]] burada yanlış olurdu çünkü \"kapalı kalma\" tek seferlik tamamlanan bir eylem değildir."}, {"sentence": "The new policy will not take effect until all departments have completed the required training.", "answer_word": "until", "reasoning": "\"will not take effect\" ifadesi [[b]]\"not...until\"[[/b]] kalıbının bir parçasıdır ve politika o ana KADAR yürürlüğe girmeyecek, ancak ondan SONRA girecek anlamını taşır → doğru cevap [[right]]\"until\"[[/right]]dür; [[wrong]]\"by\"[[/wrong]] kullanılsaydı tam tersi bir beklenti (en geç o tarihte yürürlükte olması) yaratırdı."}, {"sentence": "The construction company promised that the new bridge would be completed by the end of the year, although the surrounding roadworks might continue a little longer.", "answer_word": "by", "reasoning": "Köprünün belirli bir tarihe kadar TAMAMLANMIŞ olması beklendiği (bir teslim tarihi/deadline mantığı) için doğru cevap [[right]]\"by\"[[/right]]dır; yol çalışmalarının SÜRMESİ ayrı, süreklilik bildiren bir durumdur ve orada [[wrong]]\"until\"[[/wrong]] kullanılması gerekirdi."}]}$tagbd$::jsonb WHERE id = '9ef40305-637c-4dcb-befa-b20d816a3be8';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "although/despite/in spite of hepsi \"...e rağmen\" anlamını taşır ama ardından FARKLI bir unsur ister:", "items": [{"heading": "although vs despite/in spite of", "badge": "Ardından Ne Gelir?", "sub_rules": [{"condition": "[[q]]although/though/even though[[/q]] ardından gelmesi gereken:", "from": "although + S + V", "to": "tam cümlecik (özne + yüklem)"}, {"condition": "[[q]]despite/in spite of[[/q]] ardından gelmesi gereken:", "from": "despite + noun/-ing", "to": "isim ya da gerund (ASLA tam cümlecik değil)"}]}, {"heading": "\"despite\" + Tam Cümlecik Tuzağı", "body": [{"type": "text", "text": "Bir şıkta [[amber]]\"despite\"[[/amber]] yazıp hemen ardından özne+yüklemli bir cümlecik varsa o şık [[dark]]KESİNLİKLE YANLIŞTIR[[/dark]] — bu YDS'nin en sık kullandığı tuzaklardan biridir."}]}, {"heading": "however/nevertheless: Bağlaç Değil, Cümle Zarfı", "body": [{"type": "text", "text": "[[q]]however/nevertheless[[/q]] bağlaç değil, cümle zarfıdır: iki tam cümleyi noktalı virgül veya nokta ile ayırarak bağlar, doğrudan bir cümleciğin başına gelip onu diğerine bağlayamaz."}]}], "examples": [{"sentence": "Although the project faced severe budget cuts, the team managed to deliver the prototype on schedule.", "answer_word": "Although", "reasoning": "Boşluktan sonra \"the project faced\" (özne+yüklem, tam cümlecik) geldiği için [[wrong]]\"Despite\"[[/wrong]] yanlıştır — doğru cevap [[right]]\"Although\"[[/right]]tur. Eğer cümle isim öbeğiyle devam etseydi, o zaman \"Despite\" doğru olurdu."}, {"sentence": "In spite of her lack of experience, she was offered the managerial position.", "answer_word": "In spite of", "reasoning": "Boşluktan sonra bir isim öbeği (\"her lack of experience\") geldiği için [[wrong]]\"Even though\"[[/wrong]] yanlıştır — doğru cevap [[right]]\"In spite of\"[[/right]] ya da \"Despite\"tir. Eğer cümle özne+yüklemli bir cümlecikle devam etseydi, o zaman \"Despite\" doğru olurdu."}, {"sentence": "Despite the heavy rain, the marathon organizers decided not to cancel the event.", "answer_word": "Despite", "reasoning": "Boşluktan sonra bir isim öbeği (\"the heavy rain\") geldiği için [[wrong]]\"Although\"[[/wrong]] yanlıştır — doğru cevap [[right]]\"Despite\"[[/right]] ya da \"In spite of\"tur; [[wrong]]\"However\"[[/wrong]] ise bir bağlaç değil cümle zarfı olduğu için burada bir cümleciğin başına gelip onu diğerine doğrudan bağlayamaz, bu yüzden bu konumda hiçbir zaman doğru cevap olamaz."}, {"sentence": "The negotiations collapsed at the last minute. However, both sides agreed to resume talks the following month.", "answer_word": "However", "reasoning": "Burada iki TAM cümle nokta ile ayrılmış, aralarında bir zıtlık var — bu [[b]]\"however\"[[/b]]ın tam da kullanıldığı yapıdır (cümle zarfı olarak iki bağımsız cümleyi bağlar) → doğru cevap [[right]]\"However\"[[/right]]dır; [[wrong]]\"Despite\"[[/wrong]] ya da [[wrong]]\"Although\"[[/wrong]] burada doğrudan kullanılamaz çünkü ikisi de bağımsız bir cümlenin başında tek başına duramaz, bir cümleciğe bağlanmaları gerekir."}]}$tagbd$::jsonb WHERE id = '8429f4f4-29d8-46d3-b405-25862bb60e54';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Bir ismin sayılabilir mi sayılamaz mı olduğunu anlamanın en hızlı yolu -s ekini ve [[q]]\"a/an\"[[/q]] uyumunu kontrol etmektir:", "items": [{"heading": "Hızlı Test: -s ve a/an", "badge": "Sayılabilir mi?", "body": [{"type": "text", "text": "İsim çoğul eki (-s) alabiliyor ve [[q]]\"a/an\"[[/q]] ile kullanılabiliyorsa SAYILABİLİRdir (a book → books); tekil kalıyor, [[q]]\"a/an\"[[/q]] ALAMIYOR ve [[q]]\"much/little/a bit of\"[[/q]] ile eşleşiyorsa SAYILAMAZdır."}]}, {"heading": "Türkçede Çoğul Hissettiren ama Sayılamaz Olanlar", "body": [{"type": "text", "text": "[[amber]]information, advice, furniture, news, luggage[[/amber]] gibi kelimeler Türkçede çoğul/sayılabilir gibi hissettirse de İngilizcede [[dark]]SAYILAMAZDIR[[/dark]], bu YDS'nin klasik tuzağıdır."}, {"type": "example_check", "correct": "a piece of information / a bit of advice", "wrong_note": "\"an information\", \"informations\" her zaman yanlıştır"}]}, {"heading": "Bağlama Göre Değişen Kelimeler", "body": [{"type": "text", "text": "Bazı kelimeler bağlama göre HEM sayılabilir HEM sayılamaz kullanılabilir ve anlamı değişir: [[q]]\"paper\"[[/q]] (sayılamaz: kağıt maddesi / sayılabilir: [[q]]a paper[[/q]] = makale, gazete)."}]}], "examples": [{"sentence": "Could you give me some advice about how to fix this printer?", "answer_word": "some advice", "reasoning": "\"advice\" sayılamayan bir isim olduğu için \"a/an\" ile kullanılamaz, doğru cevap [[right]]\"some advice\"[[/right]] ya da \"a piece of advice\"tir; [[wrong]]\"an advice\"[[/wrong]] veya [[wrong]]\"advices\"[[/wrong]] gibi şıklar her zaman yanlıştır."}, {"sentence": "The professor published several papers on climate change last year.", "answer_word": "papers", "reasoning": "Burada \"paper\" SAYILABİLİR bir anlamda (makale) kullanıldığı için çoğul eki alabilir ve doğru cevap [[right]]\"papers\"[[/right]]tır; cümle kağıt maddesinden bahsetseydi doğru cevap sayılamaz haliyle tekil [[wrong]]\"paper\"[[/wrong]] olurdu."}, {"sentence": "The airline only allows one piece of luggage per passenger on this flight.", "answer_word": "luggage", "reasoning": "\"luggage\" Türkçede çoğul/sayılabilir gibi hissettirse de İngilizcede SAYILAMAZ bir isimdir, bu yüzden [[wrong]]\"a luggage\"[[/wrong]] ya da [[wrong]]\"luggages\"[[/wrong]] asla kullanılmaz; doğru kullanım bölücü ifade \"a piece of luggage\"dır, boşluğa sadece tekil [[right]]\"luggage\"[[/right]] gelir."}, {"sentence": "Have you heard the news about the merger? It's all over the office.", "answer_word": "news", "reasoning": "\"news\" sonu -s ile bitmesine rağmen SAYILAMAZ bir isimdir ve her zaman tekil fiille kullanılır → doğru cevap [[right]]\"news\"[[/right]]tir; [[wrong]]\"a news\"[[/wrong]] ya da [[wrong]]\"news are\"[[/wrong]] gibi kullanımlar kesinlikle yanlıştır."}]}$tagbd$::jsonb WHERE id = 'a7a0e88a-885d-4c2a-8b25-3f0ca7f4cc26';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Edilgen çatıda boşluktan sonraki kelimenin türüne bak: CANLI bir fail mi, CANSIZ bir araç mı?", "items": [{"heading": "by: Fail (Kim Yaptı?)", "badge": "Canlı Özne", "body": [{"type": "text", "text": "Edilgen cümlelerde eylemi GERÇEKLEŞTİREN KİŞİ ya da ÖZNE (bir fail) [[q]]\"by\"[[/q]] ile belirtilir."}, {"type": "example_check", "correct": "The window was broken by the boy", "wrong_note": "camı kıran çocuk — bir FAİL"}]}, {"heading": "with: Araç (Ne ile Yapıldı?)", "badge": "Cansız Alet/Madde", "body": [{"type": "text", "text": "Eylemi gerçekleştirmek için kullanılan ARAÇ/ALET/MADDE [[q]]\"with\"[[/q]] ile belirtilir."}, {"type": "example_check", "correct": "The window was broken with a stone", "wrong_note": "kullanılan araç taş — fail değil"}]}, {"heading": "İkisi Birlikte Kullanılabilir", "body": [{"type": "text", "text": "[[q]]by[[/q]] ve [[q]]with[[/q]] aynı cümlede birlikte de bulunabilir: \"The window was broken by the boy with a stone.\" Boşluktan sonraki kelimenin türüne bak: CANLI bir fail (kişi, hayvan, kurum, hatta \"the storm/the wind\" gibi doğa güçleri) geliyorsa [[q]]by[[/q]] doğrudur; CANSIZ bir alet/madde/malzeme geliyorsa [[q]]with[[/q]] doğrudur."}]}], "examples": [{"sentence": "The ancient vase was accidentally knocked over and broken by one of the museum visitors.", "answer_word": "by", "reasoning": "Boşluktan sonra bir KİŞİ (fail) geldiği için doğru cevap [[right]]\"by\"[[/right]]dır; cam kıran araç değil, bir insan olduğu için [[wrong]]\"with\"[[/wrong]] burada yanlış olur."}, {"sentence": "The old wooden door was sealed shut with a thick layer of dried paint.", "answer_word": "with", "reasoning": "Boşluktan sonra CANSIZ bir madde (boya) geldiği ve bu madde kapıyı kapatmak için kullanılan ARAÇ olduğu için doğru cevap [[right]]\"with\"[[/right]]tir; [[wrong]]\"by\"[[/wrong]] burada yanlıştır çünkü boya bir fail değildir."}, {"sentence": "The old barn was completely destroyed by a powerful tornado that swept through the region.", "answer_word": "by", "reasoning": "Boşluktan sonra CANLI bir doğa gücü (fail) geldiği için doğru cevap [[right]]\"by\"[[/right]]dır; [[wrong]]\"with\"[[/wrong]] burada yanlıştır çünkü tornado bir araç değil, eylemi gerçekleştiren faildir."}, {"sentence": "The fragile artifact was carefully cleaned with a soft-bristled brush before being placed in the display case.", "answer_word": "with", "reasoning": "Boşluktan sonra CANSIZ bir alet (fırça) geldiği ve bu alet temizlik için kullanılan ARAÇ olduğu için doğru cevap [[right]]\"with\"[[/right]]tir; [[wrong]]\"by\"[[/wrong]] burada yanlıştır çünkü fırça bir fail değildir."}]}$tagbd$::jsonb WHERE id = '5314db6b-bdb0-464f-b2e3-d11c21f7e4b1';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Tip 2, ŞİMDİKİ zamanda gerçek olmayan veya gerçekleşmesi çok düşük bir durumu anlatır: [[q]]if + past simple[[/q]], [[q]]would + V1[[/q]]:", "items": [{"heading": "Tip 2 Kalıbı", "badge": "Temel Yapı", "body": [{"type": "text", "text": "Şimdiki zamanda gerçek olmayan veya gerçekleşmesi çok düşük bir durumu anlatır."}, {"type": "example_check", "correct": "If I had more time, I would travel more", "wrong_note": "şimdiki zamanda gerçek olmayan hayali bir durum anlatır"}]}, {"heading": "\"were\" Tuzağı: Özne Ne Olursa Olsun", "body": [{"type": "text", "text": "[[q]]\"Be\"[[/q]] fiili if cümleciğinde kullanıldığında, özne ne olursa olsun ([[amber]]I/he/she/it[[/amber]] dahil) [[ok]]\"were\"[[/ok]] tercih edilir, [[bad]]\"was\"[[/bad]] değil — bu resmi/akademik İngilizce'de ve YDS'de aranan kuraldır."}, {"type": "example_check", "correct": "If I were you, I would apologize", "wrong_note": "\"was\" günlük konuşmada bazen görülse de sınavda \"were\" doğru kabul edilir"}]}], "examples": [{"sentence": "If she were richer, she would buy that house.", "answer_word": "were", "reasoning": "Şimdiki zamanda gerçek olmayan bir durum (zengin değil) anlatıldığı için doğru cevap [[right]]\"were\"[[/right]]dir — [[wrong]]\"was\"[[/wrong]] değil."}, {"sentence": "If he knew the answer, he would raise his hand.", "answer_word": "knew", "reasoning": "Şimdiki zamanda gerçek olmayan bir durum (cevabı bilmiyor) anlatıldığı için doğru cevap [[right]]\"knew\"[[/right]]dir, [[wrong]]\"knows\"[[/wrong]] ya da [[wrong]]\"will know\"[[/wrong]] değil. Benzer şekilde \"If I were in your position, I would accept the offer immediately\" cümlesinde de özne \"I\" olmasına rağmen doğru cevap yine [[right]]\"were\"[[/right]]dir, [[wrong]]\"was\"[[/wrong]] değil."}, {"sentence": "If I had wings, I would fly to every corner of the world.", "answer_word": "had", "reasoning": "Cümlenin ana kısmında zaten \"would fly\" bulunduğu ve şimdiki zamanda gerçek olmayan hayali bir durum (kanadı yok) anlatıldığı için if cümleciğinde doğru cevap past simple olan [[right]]\"had\"[[/right]]tir; [[wrong]]\"have\"[[/wrong]] ya da [[wrong]]\"will have\"[[/wrong]] kullanmak bu hayali/gerçek-dışı anlamı bozar."}, {"sentence": "If the company were more flexible with remote work, more employees would stay long-term.", "answer_word": "were", "reasoning": "Özne \"the company\" (it) olmasına rağmen, \"be\" fiili if cümleciğinde Tip 2'de her özneyle [[right]]\"were\"[[/right]] ister → doğru cevap [[right]]\"were\"[[/right]]dir, [[wrong]]\"was\"[[/wrong]] değil; bu kural özne insan olmasa bile değişmez."}]}$tagbd$::jsonb WHERE id = 'fddda164-3aeb-4c84-966a-a662a6df7c6e';
